<?php require __DIR__.'/app/bootstrap.php'; $pageTitle='Shop — NEXT TECH'; $q=trim($_GET['q']??''); $stmt=db()->prepare("SELECT * FROM products WHERE status='active' AND (?='' OR name LIKE ?) ORDER BY created_at DESC"); $stmt->execute([$q,'%'.$q.'%']); $products=$stmt->fetchAll(); require __DIR__.'/includes/header.php'; ?>
<section class="page-intro"><span class="eyebrow">THE COLLECTION</span><h1>Shop Products</h1><p>Explore technology essentials selected for performance and reliability.</p></section><form class="search-form" method="get"><input name="q" value="<?=e($q)?>" placeholder="Search routers, cameras, accessories…"><button class="btn btn-primary">Search</button></form><div class="product-grid"><?php foreach($products as $p): ?><article class="product-card"><a href="<?=e(url('product.php?slug='.rawurlencode($p['slug'])))?>"><div class="product-image"><?php if($p['image']): ?><img src="<?=e(url('uploads/products/'.$p['image']))?>" alt="<?=e($p['name'])?>"><?php else: ?><span>◇</span><?php endif; ?></div><h3><?=e($p['name'])?></h3></a><p class="price"><?=money($p['price'])?></p><form method="post" action="<?=e(url('cart.php'))?>"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="product_id" value="<?=(int)$p['id']?>"><button class="btn btn-primary" name="add" value="1">Add to Cart</button></form></article><?php endforeach; ?><?php if(!$products): ?><p class="empty-state">No products found.</p><?php endif; ?></div>
<?php require __DIR__.'/includes/footer.php'; ?>
